// InitTracing configures opentelemetry exporter and tracer provider.
func InitTracing(ctx context.Context, collectorAddress string, samplingRate int) (*sdktrace.TracerProvider, []otelgrpc.Option, error) {
	var tp *sdktrace.TracerProvider

	hostname, err := os.Hostname()
	if err != nil {
		return nil, nil, fmt.Errorf("get hostname: %w", err)
	}

	res := resource.NewWithAttributes(
		semconv.SchemaURL,
		semconv.ServiceNameKey.String(tracingServiceName),
		semconv.HostNameKey.String(hostname),
		semconv.ProcessPIDKey.Int64(int64(os.Getpid())),
	)

	exporter, err := otlptracegrpc.New(ctx,
		otlptracegrpc.WithEndpoint(collectorAddress),
		otlptracegrpc.WithInsecure(),
	)
	if err != nil {
		return nil, nil, err
	}

	// Only emit spans when the kubelet sends a request with a sampled trace
	sampler := sdktrace.NeverSample()
	// Or, emit spans for a fraction of transactions
	if samplingRate > 0 {
		sampler = sdktrace.TraceIDRatioBased(float64(samplingRate) / float64(1000000))
	}
	// batch span processor to aggregate spans before export.
	bsp := sdktrace.NewBatchSpanProcessor(exporter)
	tp = sdktrace.NewTracerProvider(
		sdktrace.WithSampler(sdktrace.ParentBased(sampler)),
		sdktrace.WithSpanProcessor(bsp),
		sdktrace.WithResource(res),
	)
	tmp := propagation.NewCompositeTextMapPropagator(propagation.TraceContext{}, propagation.Baggage{})

	otel.SetTracerProvider(tp)
	otel.SetTextMapPropagator(tmp)
	opts := []otelgrpc.Option{otelgrpc.WithPropagators(tmp), otelgrpc.WithTracerProvider(tp)}

	return tp, opts, nil
}

	"github.com/dtapps/allinssl_plugins/core"
	"github.com/dtapps/allinssl_plugins/xppanel/openapi"
	"github.com/dtapps/allinssl_plugins/xppanel/types"
)

// 域名绑定证书
// domain: 域名
// isBind: 是否已绑定
func Action(openapiClient *openapi.Client, domain string, certBundle *core.CertBundle) (isBound bool, err error) {

	// 1. 获取域名列表
	var queryDomainListResp types.CommonResponse[[]types.SiteQueryDomainListResponse]
	_, err = openapiClient.R().
		SetQueryParams(map[string]string{
			"p":         "1",    // 页码
			"p_size":    "100",  // 每页数量
			"site_name": domain, // 域名
		}).
		SetResult(&queryDomainListResp).
		SetContentType("application/json").
		SetForceResponseContentType("application/json").
		Get("/siteList")
	if err != nil {
		return false, fmt.Errorf("获取域名列表错误: %w", err)
	}
	if queryDomainListResp.Code != types.CodeSuccess {
		return false, fmt.Errorf("获取域名列表失败: %s", queryDomainListResp.Message)
	}
	if len(queryDomainListResp.Data) <= 0 {
		return false, fmt.Errorf("没有找到匹配的域名: %s", domain)
	}

	// 2. 检查域名是否配置了现存证书
	var siteID int
	for _, item := range queryDomainListResp.Data {
		// 检查域名是否包含传入的域名
		if item.Name == domain {
			siteID = item.ID // 找到匹配的域名，记录站点ID
			break
		}
	}

	// 3. 更新域名信息
	var updateDomainInfoResp types.CommonResponse[any]
	_, err = openapiClient.R().
		SetBody(map[string]any{
			"id":  siteID,                 // 域名
			"key": certBundle.Certificate, // 证书完整链
			"pem": certBundle.PrivateKey,  // 证书私钥
		}).
		SetResult(&updateDomainInfoResp).
		SetContentType("application/json").
		SetForceResponseContentType("application/json").
		Post("/setSSL")
	if err != nil {
		return false, fmt.Errorf("更新域名信息错误: %w", err)
	}
	if updateDomainInfoResp.Code != types.CodeSuccess {
		return false, fmt.Errorf("更新域名信息失败: %s", updateDomainInfoResp.Message)
	}

	return false, nil
}

