use tokio::net::TcpStream;
use tokio::time::{timeout, Duration};

#[tokio::test]
async fn test_server_accepts_connections() {
    // Start server in background
    let listener = tokio::net::TcpListener::bind("<IP_ADDRESS>:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();

    // Accept connections in background
    tokio::spawn(async move {
        loop {
            let (stream, _) = listener.accept().await.unwrap();
            drop(stream);
        }
    });

    // Give server time to start
    tokio::time::sleep(Duration::from_millis(100)).await;

    // Try to connect
    let result = timeout(
        Duration::from_secs(1),
        TcpStream::connect(format!("<IP_ADDRESS>:{port}"))
    ).await;

    assert!(result.is_ok(), "Should be able to connect to server");
}

#[tokio::test]
async fn test_multiple_connections() {
    let listener = tokio::net::TcpListener::bind("<IP_ADDRESS>:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();

    // Accept connections in background
    tokio::spawn(async move {
        loop {
            let (stream, _) = listener.accept().await.unwrap();
            drop(stream);
        }
    });

    // Give server time to start

suffix:
.await;

    // Connect multiple times
    for i in 0..5 {
        let result = timeout(
            Duration::from_secs(1),
            TcpStream::connect(format!("<IP_ADDRESS>:{port}"))
        ).await;

        assert!(result.is_ok(), "Connection {i} should succeed");
    }
}

