        {
            const byte lf = (byte)'\n';
            var crlf = "\r\n"u8;

            var startOfSegment = buffer.Start;
            var position = startOfSegment;
            var findPos = buffer.Start;
            var checkForEndOfLine = false;
            while (buffer.

suffix:
)
            {
