suffix:
			counterMap.put(str, mutableInt2);
		} else {
			mutableInt.increment();
		}
	}

	public void clear() {
		counterMap.clear();
	}

	public Map<String, MutableInt> getCounterMap() {
		return counterMap;
	}

	public static void main(String[] args) {
		StringCounter stringCounter = new StringCounter();

		for (int i = 0; i < 10; i++) {
			String ss = String.valueOf(i);

