        assert_eq!(track.artist, "Artist");
        assert_eq!(track.title, "Title");
        assert!(track.start_time.is_none());
        assert!(track.end_time.is_none());
        assert!(track.play_time.is_none());
    }

    #[test]
    fn new_track_with_time() {
        let start_time =

