	logEvent(getAnalytics(), 'firestore_read', {
		site: document.title || 'kurosearch_v3'
	});

export const logFirestoreWrite = async () =>
	logEvent(getAnalytics(), 'firestore_write', {
		site: document.title || 'kurosearch_v3'
	});

