			Name:      DropsTotalKey,
			Help:      "Total number of dropped items from the queue due to exceeding retry threshold",
		}, []string{"name"}),
	}
}

func (p queueMetricsProvider) NewDepthMetric(name string) workqueue.GaugeMetric {
