export function useIsTouching() {
   const { gl } = useThree();
   const movingRef = useRef(false);
   useEffect(() => {
      const elem = gl.domElement as HTMLElement;

      const handlePointerDown = (e: PointerEvent) => {
         if (e.pointerType === "touch") {
            movingRef.current = true;
         }
      };
      const handlePointerUp = (e: PointerEvent) => {
         if (e.pointerType === "touch") {
            movingRef.current = false;
         }
      };
      movingRef.current = elem.matches(":hover");

      const handlePointerOver = (e: PointerEvent) => {
         if (e.pointerType !== "touch") {
            movingRef.current = true;
         }
      };
      const handlePointerOut = (e: PointerEvent) => {
         if (e.pointerType !== "touch") {
            movingRef.current = false;
         }
      };

      elem.addEventListener("pointerdown", handlePointerDown);
      elem.addEventListener("pointerup", handlePointerUp);
      elem.addEventListener("pointercancel", handlePointerUp);
      elem.addEventListener("pointerover", handlePointerOver);
      elem.addEventListener("pointerout", handlePointerOut);

      return () => {
         elem.removeEventListener("pointerdown", handlePointerDown);
         elem.removeEventListener("pointerup", handlePointerUp);
         elem.removeEventListener("pointercancel", handlePointerUp);
         elem.removeEventListener("pointerover", handlePointerOver);
         elem.removeEventListener("pointerout", handlePointerOut);
      };
   }, [gl]);

   return movingRef;
}

