use tokio::net::TcpStream;
use tokio::time::{timeout, Duration};

#[tokio::test]
async fn test_server_accepts_connections() {
    // Start server in background
    let listener = tokio::net::TcpListener::bind("<IP_ADDRESS>:0").await.unwrap();
