namespace Rtsp.Utils
{
    public static class ReadOnlySequenceExtensions
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static (SequencePosition endOfLinePos, SequencePosition startOfLinePos)? FindEndOfLine(in this ReadOnlySequence<byte> buffer)
        {
            const byte lf = (byte)'\n';
            var crlf = "\r\n"u8;

            var startOfSegment = buffer.Start;
            var position = startOfSegment;
            var findPos = buffer.Start;
            var checkForEndOfLine = false;
            while (buffer.

suffix:
)
            {
                if (segment.Length == 0)
                    continue;

                if (checkForEndOfLine)
                {
                    var nbToskip = segment.Span[0] == lf ? 1 : 0;
                    return (findPos, buffer.GetPosition(nbToskip, startOfSegment));
                }

                var pos = segment.Span.IndexOfAny(crlf);
                if (pos != -1)
                {
                    findPos = buffer.GetPosition(pos, startOfSegment);
                    // handle \n only
                    if (segment.Span[pos] == lf)
                    {
                        return (findPos, buffer.GetPosition(pos + 1, startOfSegment));
                    }
                    if (pos + 1 < segment.Length)
                    {
                        // handle \r\n ou \r other in same segment
                        var nbToskip = segment.Span[pos + 1] == lf ? 2 : 1;
                        return (findPos, buffer.GetPosition(pos + nbToskip, startOfSegment));
                    }

                    // need to wait for next segment
                    checkForEndOfLine = true;
                }

                startOfSegment = position;
            }
            return default;
        }
    }
}

type FetchState<T> = {
  data: T;
  status: 'initial' | 'loading' | 'success' | 'error';
  isLoading: boolean;
  isSuccess: boolean;
  isError: boolean;
};

/**
 * A helper hook to fetch data from an REST API.
 *
 * This is useful for fetching data outside of the GraphQL API in scenarios
 * where the data needs to be longterm cached in the browser.
 * As all GraphQL queries use POST requests, they are not cached by the browser
 * if the API returns caching related headers such as `Cache-Control` or `ETag`.
 * This hook uses standard `fetch` API which performs a GET request and thus
 * allows the browser to cache the response when needed.
 */
export function useFetch<T>(params: {
  url: string;
  initialData: T;
  enabled?: boolean;
}): FetchState<T>;
export function useFetch<T>(params: {
  url: string;
  initialData?: T;
  enabled?: boolean;
}): FetchState<T | undefined>;
export function useFetch<T>({
  url,
  initialData = undefined,
  enabled = true,
}: {
  url: string;
  initialData?: T;
  enabled?: boolean;
}) {
  const [state, setState] = useState<{
    data?: T;
    status: 'initial' | 'loading' | 'success' | 'error';
  }>({
    data: initialData,
    status: 'initial',
  });

  useEffect(() => {
    async function fetchData(signal: AbortSignal) {
      try {
        setState(p => ({ ...p, status: 'loading' }));

        const response = await fetch(url, { signal });

        if (response.ok) {
          const newData = await response.json();
          setState({ data: newData, status: 'success' });
        } else {
          setState(p => ({ ...p, status: 'error' }));
        }
      } catch (err: any) {
        // Ignore abort errors
        if (err.name === 'AbortError') return;

        console.error('Error fetching data:', err);
        setState(p => ({ ...p, status: 'error' }));
      }
    }

    if (enabled) {
      const abortController = new AbortController();

      fetchData(abortController.signal);

      return () => {
        abortController.abort();
      };
    }
  }, [enabled, url]);

  return {
    ...state,
    isLoading: state.status === 'loading',
    isSuccess: state.status === 'success',
    isError: state.status === 'error',
  };
}

