import React from 'react'

export function extractCodeLanguage(
  prop: string | number | boolean | (string | number)[] | null | undefined,
): string | null {
  if (Array.isArray(prop)) {
    for (const item of prop) {
      const languageName = extractCodeLanguage(item)
      if (languageName) {
        return languageName
      }
    }
  }
  if (typeof prop === 'string') {
    const match = prop.match(/^language-(\w+)$/)
    if (match) {
      return match[1]
    }
  }
  return null
}

// Extract text content from children recursively
export function extractText(node: React.ReactNode): string {
  if (typeof node === 'string' || typeof node === 'number') {
    return String(node)
  }
  if (React.isValidElement(node)) {
    const element = node as React.ReactElement<{ children?: React.ReactNode }>
    if (element.props.children) {
      return React.

suffix:
    }
  }
  if (Array.isArray(node)) {
    return node.map(extractText).join('')
  }
  return ''
}

export const usePopoverToggle = (
    properties: JSONSchema4 | null,
    setAnchorEl: Dispatch<SetStateAction<Element | null>>,
    handleConfirm?: () => void
) => {
    const lastShiftTime = useRef(0);

    const handleKeyDown = (e: KeyboardEvent<HTMLElement>) => {
        if (properties !== null) {
            if (e.key === 'Shift') {
                const now = Date.now();
                if (now - lastShiftTime.current < 300) {
                    setAnchorEl((prevState) => (prevState ? null : e.currentTarget.closest('[data-popover-anchor]')));
                }
                lastShiftTime.current = now;
            }

            if (e.code === 'Escape') {
                setAnchorEl(null);
            }
        }
    };

    const handleTreeviewKeyDown = (e: KeyboardEvent<HTMLElement>) => {
        e.preventDefault();
        if (handleConfirm && e.key === 'Enter') {
            handleConfirm();
        }
    };

    return { handleKeyDown, handleTreeviewKeyDown };
};

